     1→/**
     2→ * 路由层契约测试基座（质量优化 Stage 2）：统一 Express 装配 / JWT 令牌签发 / DB 查询桩。
     3→ * 文件名不匹配 vitest 测试 glob（非 *.test.ts），仅供各路由测试文件导入，不会被当作用例执行。
     4→ */
     5→import express, { Router } from 'express';
     6→import { signToken, AuthUser, UserRole } from '../auth/auth';
     7→
     8→/** 测试环境变量：JWT 密钥与限流阈值均惰性读取，导入被测路由前后调用皆可 */
     9→export function applyTestEnv() {
    10→  process.env.JWT_SECRET = process.env.JWT_SECRET || 'unit-test-secret';
    11→  // 契约测试共享内存限流计数器（默认 30/min 会误伤多断言用例）
    12→  process.env.RATE_LIMIT_MAX = '100000';
    13→}
    14→
    15→/** 签发指定角色的访问令牌（与生产同源 signToken，鉴权链路真实生效） */
    16→export function tokenFor(role: UserRole = 'ADMIN', id = 1): string {
    17→  const user: AuthUser = {
    18→    id,
    19→    username: `u${id}`,
    20→    displayName: `用户${id}`,
    21→    department: '测试部',
    22→    role,
    23→    mustChangePassword: false,
    24→  };
    25→  return signToken(user);
    26→}
    27→
    28→/** authMiddleware 回查用户状态所需行（ACTIVE；与 users 表 SELECT 列对齐） */
    29→export function activeUserRow(role: UserRole = 'ADMIN', id = 1) {
    30→  return {
    31→    id,
    32→    username: `u${id}`,
    33→    display_name: `用户${id}`,
    34→    department: '测试部',
    35→    role,
    36→    status: 'ACTIVE',
    37→    must_change_password: 0,
    38→  };
    39→}
    40→
    41→export interface DbStubRule {
    42→  /** SQL 片段或正则（命中即返回该结果） */
    43→  match: string | RegExp;
    44→  /** 返回行集（或惰性函数，避免用例间共享可变对象） */
    45→  rows: unknown[] | (() => unknown[]);
    46→}
    47→
    48→/**
    49→ * 按 SQL 分派 getPool().query 的桩实现。
    50→ * 未命中规则直接抛错（而非静默返回空集），避免用例因桩缺配而"假通过"。
    51→ */
    52→export function dbStub(rules: DbStubRule[]) {
    53→  return async (sql: string, _params?: unknown[]) => {
    54→    for (const rule of rules) {
    55→      const hit = typeof rule.match === 'string' ? sql.includes(rule.match) : rule.match.test(sql);
    56→      if (hit) {
    57→        const rows = typeof rule.rows === 'function' ? (rule.rows as () => unknown[])() : rule.rows;
    58→        return [rows];
    59→      }
    60→    }
    61→    throw new Error(`[routeTestKit] 未匹配的 SQL: ${String(sql).slice(0, 160)}`);
    62→  };
    63→}
    64→
    65→/** 装配被测路由（express.json 与生产一致；路由自带 authMiddleware 链） */
    66→export function buildApp(mountPath: string, router: Router) {
    67→  const app = express();
    68→  app.use(express.json({ limit: '20mb' }));
    69→  app.use(mountPath, router);
    70→  return app;
    71→}
    72→

