   180→      ]),
   181→    );
   182→    const res = await request(app)
   183→      .post(url)
   184→      .set('Authorization', `Bearer ${tokenFor('ANALYST', 7)}`)
   185→      .send({ oldPassword: 'Wrong#Pass9', newPassword: 'N3w#Passw0rd' });
