     7→
     8→const router = Router();
     9→
    10→/** 困难样本类型定义 */
    11→interface AdversarialSample {
    12→  id: number;
    13→  original_query: string;
    14→  original_sql: string;
    15→  error_message: string;
    16→  data_source_id: string;
