    21→  created_at: Date;
    22→}
    23→
    24→/** 列表查询（管理员） - 按优先级分数排序 */
    25→router.get('/', authMiddleware, requireRole('ADMIN'), async (req: Request, res: Response) => {
    26→  try {
    27→    const samples = await prioritizePendingSamples();
    28→
    29→    if (samples.length === 0) {
    30→      return res.json({ success: true, samples: [], message: '暂无待审核样本' });
    31→    }
    32→
    33→    // 响应简化版本（前端不需要所有内部字段）
    34→    const responseSamples = samples.map((s): any => ({
    35→      id: s.id,
    36→      original_query: s.originalQuery,
    37→      original_sql: s.originalSQL,
    38→      error_message: s.errorMessage,
    39→      data_source_id: s.dataSourceId,
    40→      user_id: s.userId,
    41→      annotation_status: s.annotationStatus,
    42→      expected_sql: s.expectedSQL,
    43→      resolved_strategy: s.resolvedStrategy,
    44→      created_at: s.createdAt,
    45→      // Priority scores
    46→      total_score: s.totalScore,
    47→      rank: s.rank,
    48→    }));
    49→
    50→    res.json({ 
    51→      success: true, 
    52→      samples: responseSamples,
    53→      priorityInfo: {
    54→        totalCount: samples.length,
    55→        topScore: samples[0].totalScore,
    56→        avgScore: Math.round(samples.reduce((sum, s) => sum + s.totalScore, 0) / samples.length),
    57→        sortingMethod: 'active_learning_multi_factor',
    58→      },
    59→    });
    60→  } catch (err: any) {
    61→    logger.error('[Admin] Fallback Approval Load Error:', err);
    62→    res.status(500).json({ error: '加载样本失败：' + err.message });
    63→  }
    64→});
    65→
    66→/** 批量操作（approve/reject） */
    67→router.post('/batch', authMiddleware, requireRole('ADMIN'), async (req: Request, res: Response) => {
    68→  const { ids, action }: { ids: number[]; action: 'approve' | 'reject' } = req.body;
    69→  
    70→  if (!ids || !Array.isArray(ids) || ids.length === 0) {
    71→    return res.status(400).json({ error: '无效的参数' });
    72→  }
    73→
    74→  try {
    75→    // 分批更新（防止 SQL 过长）
