     1→/**
     2→ * Fallback Few-Shot 示例注入与检索服务（v0.9.47 P0 重写）
     3→ *
     4→ * 闭环链路：管理员审批采纳 → injectFewShotSamples 写入独立 few_shot_examples 表 →
     5→ * fallback 策略（simpler_prompt / human_approval）按问题 bigram 相似度检索历史修正 SQL 复用。
     6→ *
     7→ * v0.9.45 版本将示例写入 knowledge_base，但其 INSERT 列（content/doc_type/updated_at）
     8→ * 与该表真实结构（chunk_text，无 doc_type/updated_at）不匹配，且会污染业务知识 RAG 检索，故独立建表。
     9→ */
    10→
    11→import { getPool } from '../infra/db.js';
    12→import { logger } from '../infra/logger.js';
    13→import { bigramOverlap } from '../query/queryFeedback.js';
    14→
    15→/** Few-Shot 示例条目（检索返回） */
    16→export interface FewShotExample {
    17→  id: number;
    18→  dataSourceId: string;
    19→  question: string;
    20→  expectedSQL: string;
    21→}
    22→
    23→/** 注入输入（snake_case，与审批 API 的样本形态一致） */
    24→export interface FewShotInjectionSample {
    25→  original_query: string;
    26→  expected_sql: string;
    27→  data_source_id: string;
    28→  sample_id?: number;
    29→}
    30→
    31→/**
    32→ * 将采纳的困难样本注入 few_shot_examples 表（分批插入，每批最多 10 条）
    33→ */
    34→export async function injectFewShotSamples(samples: FewShotInjectionSample[]): Promise<number> {
    35→  const valid = samples.filter((s) => s.original_query && s.expected_sql);
    36→  if (valid.length === 0) return 0;
    37→
    38→  const BATCH_SIZE = 10;
    39→  let inserted = 0;
    40→
    41→  for (let i = 0; i < valid.length; i += BATCH_SIZE) {
    42→    const batch = valid.slice(i, i + BATCH_SIZE);
    43→
    44→    try {
    45→      const insertPromises = batch.map((sample) =>
    46→        getPool().query(
    47→          `INSERT INTO few_shot_examples (data_source_id, question, expected_sql, sample_source, sample_id)
    48→           VALUES (?, ?, ?, 'fallback_approval', ?)`,
    49→          [sample.data_source_id || 'default', sample.original_query.slice(0, 500), sample.expected_sql, sample.sample_id ?? null]
    50→        )
    51→      );
    52→
    53→      await Promise.all(insertPromises);
    54→      inserted += batch.length;
    55→      logger.info('[FewShot] Batch injected:', { count: batch.length });
    56→    } catch (err: any) {
    57→      logger.error('[FewShot] Injection failed:', err.message);
    58→      throw new Error(`Few-Shot 注入失败：${err.message}`, { cause: err });
    59→    }
    60→  }
    61→
    62→  logger.info('[FewShot] Completed:', { inserted });
    63→  return inserted;
    64→}
    65→
    66→/**
    67→ * 检索相似 Few-Shot 示例：同数据源最近 100 条中按问题 bigram 重合打分
    68→ * （与个人 few-shot 检索同口径，见 conversationHistory.ts），取 top-k。
    69→ * 命中时异步累计 hit_count（失败不影响检索结果）。
    70→ */
    71→export async function retrieveFewShotExamples(
    72→  query: string,
    73→  dataSourceId?: string,
    74→  limit: number = 3
    75→): Promise<FewShotExample[]> {
    76→  try {
    77→    const [rows] = await getPool().query(
    78→      `SELECT id, data_source_id, question, expected_sql FROM few_shot_examples
    79→       WHERE data_source_id = ? ORDER BY id DESC LIMIT 100`,
    80→      [dataSourceId || 'default']
    81→    );
    82→
    83→    const scored = (Array.isArray(rows) ? rows : [])
    84→      .map((row: any) => ({
    85→        id: Number(row.id),
    86→        dataSourceId: String(row.data_source_id),
    87→        question: String(row.question),
    88→        expectedSQL: String(row.expected_sql),
    89→        score: bigramOverlap(query, String(row.question)),
    90→      }))
    91→      .filter((s) => s.score > 0)
    92→      .sort((a, b) => b.score - a.score)
    93→      .slice(0, Math.max(1, limit));
    94→
    95→    if (scored.length > 0) {
    96→      // fire-and-forget：命中计数仅用于运营观察，失败静默
    97→      const ids = scored.map((s) => s.id);
    98→      getPool()
    99→        .query(`UPDATE few_shot_examples SET hit_count = hit_count + 1 WHERE id IN (${ids.map(() => '?').join(',')})`, ids)
   100→        .catch((e: any) => logger.warn('[FewShot] hit_count update failed:', e?.message || e));
   101→    }
   102→
   103→    logger.debug('[FewShot] Retrieved:', { count: scored.length });
   104→    return scored.map(({ id, dataSourceId, question, expectedSQL }) => ({ id, dataSourceId, question, expectedSQL }));
   105→  } catch (err: any) {
   106→    logger.error('[FewShot] Retrieval failed:', err.message);
   107→    return [];
   108→  }
   109→}
   110→
   111→/**
   112→ * 检索单条最相似示例（human_approval 策略复用入口）：无相似样本返回 null
   113→ */
   114→export async function retrieveBestFewShot(
   115→  query: string,
   116→  dataSourceId?: string
   117→): Promise<{ question: string; sql: string } | null> {
   118→  const [best] = await retrieveFewShotExamples(query, dataSourceId, 1);
   119→  return best ? { question: best.question, sql: best.expectedSQL } : null;
   120→}
   121→

