     1→/**
     2→ * 主动学习 - PENDING 样本优先级排序算法
     3→ * 
     4→ * 核心思想：通过多因子评分模型对 PENDING 样本进行优先级排序，
     5→ * 优先处理高价值样本以提高 Few-Shot 知识库质量
     6→ */
     7→
     8→import { getPool } from '../infra/db.js';
     9→import { logger } from '../infra/logger.js';
    10→
    11→/** 样本优先级得分 */
    12→export interface SamplePriorityScore {
    13→  id: number;
    14→  originalQuery: string;
    15→  originalSQL: string;
    16→  errorMessage: string;
    17→  dataSourceId: string;
    18→  userId: number;
    19→  annotationStatus: 'PENDING' | 'IN_REVIEW' | 'APPROVED' | 'REJECTED';
    20→  expectedSQL: string | null;
    21→  resolvedStrategy: string | null;
    22→  createdAt: Date;
    23→  
    24→  // Priority scores
    25→  ageScore: number;           // 时间衰减分 (0-10)
    26→  frequencyScore: number;     // 高频错误分 (0-30)
    27→  complexityScore: number;    // 查询复杂度分 (0-25)
    28→  diversityScore: number;     // 多样性探索分 (0-10)
    29→  userWeightScore: number;    // 重要用户加权分 (0-25)
    30→  
    31→  totalScore: number;         // 总分 (0-100)
    32→  rank: number;               // 排名
    33→}
    34→
    35→/**
    36→ * 计算样本优先级分数并排序
    37→ * @param samples Raw database rows
    38→ * @returns Sorted samples with priority scores
    39→ */
    40→export async function prioritizePendingSamples(): Promise<SamplePriorityScore[]> {
    41→  try {
    42→    // 获取所有 PENDING 样本
    43→    const [pendingRows] = await getPool().query(`
    44→      SELECT id, original_query, original_sql, error_message, data_source_id, user_id, 
    45→             annotation_status, expected_sql, resolved_strategy, created_at
    46→      FROM adversarial_samples
    47→      WHERE annotation_status = 'PENDING'
    48→      ORDER BY created_at DESC
    49→    `) as any[];
    50→
    51→    if (!Array.isArray(pendingRows) || pendingRows.length === 0) {
    52→      return [];
    53→    }
    54→
    55→    // 统计各数据源的错误频率
    56→    const errorFrequencyMap = new Map<string, number>();
    57→    pendingRows.forEach(row => {
    58→      const key = row.data_source_id || 'default';
    59→      errorFrequencyMap.set(key, (errorFrequencyMap.get(key) || 0) + 1);
    60→    });
    61→    const maxFrequency = Math.max(...Array.from(errorFrequencyMap.values()), 1);
    62→
    63→    // 分析各 SQL 模板的出现次数（用于去重）
    64→    const sqlTemplateMap = new Map<string, number>();
    65→    pendingRows.forEach(row => {
    66→      const template = normalizeSQLTemplate(row.original_sql);
    67→      sqlTemplateMap.set(template, (sqlTemplateMap.get(template) || 0) + 1);
    68→    });
    69→
    70→    // 统计各用户的待审失败次数（高频踩坑用户的样本优先修复）
    71→    // v0.9.47 P0 修复：原实现读取 row.userId（DB 列为 user_id）得 undefined → totalScore 恒为 NaN，排序失效
    72→    const userFailureMap = new Map<number, number>();
    73→    pendingRows.forEach(row => {
    74→      const uid = Number(row.user_id) || 0;
    75→      userFailureMap.set(uid, (userFailureMap.get(uid) || 0) + 1);
    76→    });
    77→    const maxUserFailures = Math.max(...Array.from(userFailureMap.values()), 1);
    78→
    79→    // 为每个样本计算优先级分数
    80→    const now = new Date();
    81→    const scoredSamples: SamplePriorityScore[] = pendingRows.map((row): SamplePriorityScore => {
    82→      const dataSourceId = row.data_source_id || 'default';
    83→      const ageHours = (now.getTime() - new Date(row.created_at).getTime()) / 36e5;
    84→      
    85→      // 1. 时间衰减分 (0-10): 越老的样本分数越高，鼓励尽快审核积压样本
    86→      // exponential decay: score = 10 * e^(-age_hours / half_life), half_life = 24 hours
    87→      const ageScore = Math.min(10, Math.round(10 * Math.exp(-ageHours / 24)));
    88→
    89→      // 2. 高频错误分 (0-30): 同一数据源出现次数越多分数越高
    90→      const frequency = errorFrequencyMap.get(dataSourceId) || 1;
    91→      const frequencyScore = Math.round(30 * (frequency / maxFrequency));
    92→
    93→      // 3. 查询复杂度分 (0-25): SQL 长度、关键词数量作为复杂度指标
    94→      const complexityScore = Math.round(25 * Math.min(1, row.original_sql.length / 500));
    95→
    96→      // 4. 多样性探索分 (0-10): 基于 SQL 模板的唯一性，鼓励覆盖多样场景
    97→      const sqlTemplate = normalizeSQLTemplate(row.original_sql);
    98→      const templateCount = sqlTemplateMap.get(sqlTemplate) || 1;
    99→      const diversityScore = Math.round(10 * (1 - Math.log(templateCount) / Math.log(maxFrequency + 1)));
   100→
   101→      // 5. 高频踩坑用户加权分 (0-25): 待审队列中该用户失败次数越多，其场景优先修复价值越高
   102→      const userIdNum = Number(row.user_id) || 0;
   103→      const userWeightScore = Math.round(25 * ((userFailureMap.get(userIdNum) || 1) / maxUserFailures));
   104→
   105→      const totalScore = ageScore + frequencyScore + complexityScore + diversityScore + userWeightScore;
   106→
   107→      // v0.9.47 P0 修复：DB 行为 snake_case，此处显式映射为接口声明的 camelCase
   108→      //（原 {...row} 展开导致 originalQuery 等字段全为 undefined，审批 API 无法读到值）
   109→      return {
   110→        id: Number(row.id),
   111→        originalQuery: String(row.original_query || ''),
   112→        originalSQL: String(row.original_sql || ''),
   113→        errorMessage: String(row.error_message || ''),
   114→        dataSourceId,
   115→        userId: userIdNum,
   116→        annotationStatus: row.annotation_status,
   117→        expectedSQL: row.expected_sql ?? null,
   118→        resolvedStrategy: row.resolved_strategy ?? null,
   119→        createdAt: new Date(row.created_at),
   120→        ageScore,
   121→        frequencyScore,
   122→        complexityScore,
   123→        diversityScore,
   124→        userWeightScore,
   125→        totalScore,
   126→        rank: 0, // 待排序填充
   127→      };
   128→    });
   129→
   130→    // 按总分降序排序
   131→    scoredSamples.sort((a, b) => b.totalScore - a.totalScore);
   132→    
   133→    // 填充排名
   134→    scoredSamples.forEach((sample, index) => {
   135→      sample.rank = index + 1;
   136→    });
   137→
   138→    logger.info('[ActiveLearning] Prioritized PENDING samples:', {
   139→      count: scoredSamples.length,
   140→      topScore: scoredSamples[0]?.totalScore || 0,
   141→      avgScore: scoredSamples.reduce((sum, s) => sum + s.totalScore, 0) / scoredSamples.length,
   142→    });
   143→
   144→    return scoredSamples;
   145→  } catch (err: any) {
   146→    logger.error('[ActiveLearning] Prioritization failed:', err.message);
   147→    return []; // Fail-safe
   148→  }
   149→}
   150→
   151→/**
   152→ * 标准化 SQL 模板（去除具体数值和字符串）
   153→ * 示例："SELECT SUM(amount) FROM sales WHERE date='2024-01-01'" 
   154→ *   → "SELECT SUM(?) FROM sales WHERE date=?"
   155→ */
   156→export function normalizeSQLTemplate(sql: string): string {
   157→  return sql
   158→    .replace(/\d+/g, '?')         // 数字占位符
   159→    .replace(/'[^']*'/g, '?')     // 单引号字符串占位符
   160→    .replace(/"[^"]*"/g, '?')     // 双引号字符串占位符
   161→    .trim()
