     1→/**
     2→ * P1-2 统一日志出口：服务端运行时代码一律经 logger 输出，替代散落的 console.*。
     3→ * - 级别由 LOG_LEVEL 控制（debug/info/warn/error，默认 info），进程启动时读取一次（重启生效）
     4→ * - error 级恒输出；warn 及以上在 test 环境静默（VITEST/NODE_ENV=test），避免单测噪音
     5→ * - 底层仍走 console（零依赖）；未来引入 pino 等结构化日志设施时仅需替换本文件实现
     6→ * - eval/ 下 CLI 脚本刻意保留 console（命令行输出即用户界面），不走本封装
     7→ */
     8→type Level = 'debug' | 'info' | 'warn' | 'error';
     9→
    10→const LEVELS: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };
    11→
    12→function resolveThreshold(): number {
    13→  const raw = (process.env.LOG_LEVEL || '').trim().toLowerCase();
    14→  return raw in LEVELS ? LEVELS[raw as Level] : LEVELS.info;
    15→}
    16→
    17→const threshold = resolveThreshold();
    18→const isTest = Boolean(process.env.VITEST) || process.env.NODE_ENV === 'test';
    19→
    20→function enabled(level: Level): boolean {
    21→  if (LEVELS[level] < threshold) return false;
    22→  // test 环境只保留 error（单测断言不依赖日志输出；warn/info 刷屏干扰用例定位）
    23→  if (isTest && LEVELS[level] < LEVELS.error) return false;
    24→  return true;
    25→}
    26→
    27→export const logger = {
    28→  debug(msg: unknown, ...args: unknown[]): void {
    29→    if (enabled('debug')) console.debug(msg, ...args);
    30→  },
    31→  info(msg: unknown, ...args: unknown[]): void {
    32→    if (enabled('info')) console.log(msg, ...args);
    33→  },
    34→  warn(msg: unknown, ...args: unknown[]): void {
    35→    if (enabled('warn')) console.warn(msg, ...args);
    36→  },
    37→  error(msg: unknown, ...args: unknown[]): void {
    38→    if (enabled('error')) console.error(msg, ...args);
    39→  },
    40→};
