     1→/**
     2→ * 密码哈希模块：Node 内置 crypto.scrypt + timingSafeEqual，零外部依赖。
     3→ * P2-8 显式提参（N=2^15, r=8, p=1）+ pepper（SCRYPT_PEPPER 环境变量）。
     4→ * 新格式：`scrypt$N$r$p$P$salt$hash`（P=1 表示哈希时拼接了 pepper）；
     5→ * 旧格式：`scrypt$N$salt$hash`（4 段，隐含 r=8/p=1/无 pepper）继续兼容校验。
     6→ */
     7→import { randomBytes, scryptSync, timingSafeEqual } from 'crypto';
     8→
     9→const SCRYPT_N = 32768; // 2^15：单次哈希约 80ms，暴力破解成本翻倍
    10→const SCRYPT_R = 8;
    11→const SCRYPT_P = 1;
    12→const KEY_LEN = 64;
    13→// 128*N*r=32MB 恰好撞上 Node 默认 maxmem（33554432），显式放宽到 64MB
    14→const SCRYPT_MAXMEM = 128 * SCRYPT_N * SCRYPT_R * 2;
    15→/** 服务级密钥（pepper）：与库表分离存储，拖库后离线爆破仍需 env 配合；未配置则不启用（向后兼容） */
    16→const SCRYPT_PEPPER = process.env.SCRYPT_PEPPER || '';
    17→
