    19→const WEAK_PASSWORDS = new Set([
    20→  'admin123', 'admin888', 'password', 'password1', 'p@ssw0rd',
    21→  '12345678', '123456789', '1234567890', 'qwerty123', 'abc12345',
    22→  '11111111', '88888888', '66668888', 'letmein123', 'welcome123',
    23→]);
